UPDATE "augments" SET "Kill_Credit_Dependency"='Supported Skill directly defeats a qualifying enemy: an enemy that was not summoned (by a skill, augment or item) and has not been revived this battle. Counts: mid-battle reinforcements, hostile event units, neutrals that have turned hostile (a Traitor counts if it dies while still an enemy). Does not count: allies, neutrals, objects, summoned units, revived units. Applies both ways (enemy units with this augment get nothing for killing summoned or revived player units). USER RULING 2026-10-26.' WHERE "Augment_ID"='AUG-SOUL-ECHO' AND "Kill_Credit_Dependency" IS 'Primary Skill damage directly causes enemy KO';
UPDATE "augments" SET "Kill_Credit_Dependency"='Supported Skill directly defeats a qualifying enemy: an enemy that was not summoned (by a skill, augment or item) and has not been revived this battle. Counts: mid-battle reinforcements, hostile event units, neutrals that have turned hostile (a Traitor counts if it dies while still an enemy). Does not count: allies, neutrals, objects, summoned units, revived units. Applies both ways (enemy units with this augment get nothing for killing summoned or revived player units). USER RULING 2026-10-26.' WHERE "Augment_ID"='AUG-GOLD-HARVEST' AND "Kill_Credit_Dependency" IS 'Primary Skill damage directly causes enemy KO';
UPDATE "augments" SET "Kill_Credit_Dependency"='Supported Skill directly defeats a qualifying enemy: an enemy that was not summoned (by a skill, augment or item) and has not been revived this battle. Counts: mid-battle reinforcements, hostile event units, neutrals that have turned hostile (a Traitor counts if it dies while still an enemy). Does not count: allies, neutrals, objects, summoned units, revived units. Applies both ways (enemy units with this augment get nothing for killing summoned or revived player units). USER RULING 2026-10-26.' WHERE "Augment_ID"='AUG-TREASURE-HUNTER' AND "Kill_Credit_Dependency" IS 'Primary Skill damage directly causes enemy KO';
UPDATE "augments" SET "Notes"='Melee cleave. Hits whatever stands on the flanking tiles next to the primary target from the caster''s perspective, on any side (2026-10-26 ruling). Rewards positioning — stand where you can arc into clusters.' WHERE "Augment_ID"='AUG-WIDE-ARC' AND "Notes" IS 'Melee cleave. Only hits enemies flanking the primary target from caster''s perspective. Rewards positioning — stand where you can arc into clusters.';
UPDATE "trigger_safety" SET "col_4"='Enemy that was NOT summoned (by a skill, augment or item) and has NOT been revived this battle. Counts: mid-battle reinforcements, hostile event units (Champion, Spirits, Golems, Thief, etc.), neutrals once they have turned hostile (Wandering Monster, Bandits, Mercenaries); a Traitor counts if it dies while still an enemy. Does not count: allies, neutrals, objects, summoned units, revived units (Chaos Necromancer''s raised undead are revives). Applies both ways: enemy units with kill augments get nothing for killing summoned or revived player units. USER RULING 2026-10-26.' WHERE "11_TRIGGER_SAFETY"='TRG-006' AND "col_4" IS 'Enemy; not ally or player-summoned friendly unit';
UPDATE "trigger_safety" SET "col_13"='Kill count above 1 does not increase AP from one execution. Eligibility REVISED 2026-10-26 (USER RULING): was ''Enemy; not ally or player-summoned friendly unit''. Same kill-credit definition as all 16 kill augments (frameworks ''Kill-credit definition'').' WHERE "11_TRIGGER_SAFETY"='TRG-006' AND "col_13" IS 'Kill count above 1 does not increase AP from one execution.';
UPDATE "trigger_safety" SET "col_4"='Enemy that was NOT summoned (by a skill, augment or item) and has NOT been revived this battle. Counts: mid-battle reinforcements, hostile event units (Champion, Spirits, Golems, Thief, etc.), neutrals once they have turned hostile (Wandering Monster, Bandits, Mercenaries); a Traitor counts if it dies while still an enemy. Does not count: allies, neutrals, objects, summoned units, revived units (Chaos Necromancer''s raised undead are revives). Applies both ways: enemy units with kill augments get nothing for killing summoned or revived player units. USER RULING 2026-10-26.' WHERE "11_TRIGGER_SAFETY"='TRG-007' AND "col_4" IS 'Enemy; not ally or player-summoned friendly unit';
UPDATE "trigger_safety" SET "col_13"='Applies to Blood Harvest, Soul Harvest, Purifying Kill, and reward kill triggers unless explicitly overridden. Eligibility REVISED 2026-10-26 (USER RULING): was ''Enemy; not ally or player-summoned friendly unit''. Same kill-credit definition as all 16 kill augments (frameworks ''Kill-credit definition'').' WHERE "11_TRIGGER_SAFETY"='TRG-007' AND "col_13" IS 'Applies to Blood Harvest, Soul Harvest, Purifying Kill, and reward kill triggers unless explicitly overridden.';
UPDATE "trigger_safety" SET "col_4"='Enemy target that qualifies under the kill-credit definition (TRG-006: not summoned, not revived this battle; USER RULING 2026-10-26); primary authored Skill Power only' WHERE "11_TRIGGER_SAFETY"='TRG-008' AND "col_4" IS 'Enemy target; primary authored Skill Power only';
UPDATE "trigger_safety" SET "col_13"='Strict primary-Skill-damage-only qualification. Eligibility aligned 2026-10-26 with the kill-credit definition (Explosive Death is one of the 16 kill augments).' WHERE "11_TRIGGER_SAFETY"='TRG-008' AND "col_13" IS 'Strict primary-Skill-damage-only qualification.';
UPDATE "frameworks" SET "rule"='Minimal catalog: Direct Damage, Healing, Shield, Buff, Debuff, Utility, Summon; Physical, Fire, Water, Ice, Electric, Earth, Dark, Holy, Poison. Do not use Direct Hit, Terrain, Movement, Displacement, or Non-Elemental as core tags. ADDED 2026-10-26 (USER RULING, tags-only augment compatibility) - card-visible requirement tags: Shape = Single / Area / Weapon Shape; Reach = Melee / Ranged / Weapon Reach (Self-only, Caster Area and aura skills get no Reach tag); Has Number (the skill has a damage, heal or shield number); Costs MP (MP cost above 0); Weapon Scaling (power uses Weapon Attack Power). Weapon Shape / Weapon Reach are resolved at runtime from the equipped weapon and the card shows the weapon''s actual tags.' WHERE "id"=4 AND "rule" IS 'Minimal catalog: Direct Damage, Healing, Shield, Buff, Debuff, Utility, Summon; Physical, Fire, Water, Ice, Electric, Earth, Dark, Holy, Poison. Do not use Direct Hit, Terrain, Movement, Displacement, or Non-Elemental as core tags.';
UPDATE "frameworks" SET "rule"='Current values: Any Tile, Caster Area, Self, Self (Aura), Empty Tile, Object, plus the unit-targeted carve-outs that keep Enemy Unit / Ally Unit / Enemy Tile (see movement_targeting ''Targeting Rules'' rows dated 2026-10-26). REVISED 2026-10-26 (USER RULING): compatibility (augments and weapon passives) uses ONLY Skill tags, not Target Rules. Target Rules now only describe what the skill is aimed at. Previous text: ''Enemy Unit, Ally Unit, Self, Ground, Object, Empty Tile, etc. Compatibility uses declared Target Rules, not actual resolution frequency.''' WHERE "id"=5 AND "rule" IS 'Enemy Unit, Ally Unit, Self, Ground, Object, Empty Tile, etc. Compatibility uses declared Target Rules, not actual resolution frequency.';
UPDATE "frameworks" SET "rule"='Each passive declares compatible Skill tags, effect, delivery frequency, timing, and restrictions. (REVISED 2026-10-26: Target Rules are no longer part of compatibility - tags only.)' WHERE "id"=21 AND "rule" IS 'Each passive declares compatible Skill tags, Target Rules, effect, delivery frequency, timing, and restrictions.';
UPDATE "frameworks" SET "rule"='Determined only by Skill tags (REVISED 2026-10-26 USER RULING: Target Rules are no longer used for compatibility). Actual resolution results determine produced value after compatibility is established. Delivery may be once per Skill action, once per affected target, or once per successful hit.' WHERE "id"=41 AND "rule" IS 'Determined only by Skill effect tags and Skill Target Rules. Actual resolution results determine produced value after compatibility is established. Delivery may be once per Skill action, once per affected target, or once per successful hit.';
UPDATE "project_rules" SET "topic"='Built-in weapon passives apply to a Skill Card only when compatibility is established through the passive’s declared Compatible Skill Tags (tags only - REVISED 2026-10-26 USER RULING: Target Rules are no longer used for compatibility).

After compatibility is established, the passive resolves according to its declared delivery rule.

Delivery may be:
- Once per Skill action
- Once per affected target
- Once per successful hit

Reduced Pattern damage does not reduce passive magnitude unless the passive explicitly scales from damage dealt.

Multi-hit and multi-target Skills repeat a passive only when the passive’s declared delivery rule permits repetition.

Weapon RT Delay applies to a Skill Card only when that Skill explicitly declares Weapon RT Delay Inheritance. Weapon RT Delay is not automatically delivered by every Skill Card.' WHERE "id"=17 AND "topic" IS 'Built-in weapon passives apply to a Skill Card only when compatibility is established through the passive’s declared Compatible Skill Tags and Compatible Target Rules.

After compatibility is established, the passive resolves according to its declared delivery rule.

Delivery may be:
- Once per Skill action
- Once per affected target
- Once per successful hit

Reduced Pattern damage does not reduce passive magnitude unless the passive explicitly scales from damage dealt.

Multi-hit and multi-target Skills repeat a passive only when the passive’s declared delivery rule permits repetition.

Weapon RT Delay applies to a Skill Card only when that Skill explicitly declares Weapon RT Delay Inheritance. Weapon RT Delay is not automatically delivered by every Skill Card.';
UPDATE "project_rules" SET "topic"='Normal procedural Line 2, Impact Splash, Cleave, Cone, Adjacent, and Chain conversions cost 250 BP, are Single-base only unless restricted, replace Single, and cannot coexist with another Pattern conversion.

The converted Pattern applies to Basic Attacks and to Skill Cards only when the Skill explicitly inherits Weapon Pattern.

Compatible weapon passives resolve through the converted Pattern according to each passive’s declared Skill-tag compatibility and delivery frequency (Target Rules no longer used for compatibility, 2026-10-26).

Weapon RT Delay resolves through the converted Pattern for Basic Attacks and for Skill Cards only when the Skill explicitly declares Weapon RT Delay Inheritance.' WHERE "id"=29 AND "topic" IS 'Normal procedural Line 2, Impact Splash, Cleave, Cone, Adjacent, and Chain conversions cost 250 BP, are Single-base only unless restricted, replace Single, and cannot coexist with another Pattern conversion.

The converted Pattern applies to Basic Attacks and to Skill Cards only when the Skill explicitly inherits Weapon Pattern.

Compatible weapon passives resolve through the converted Pattern according to each passive’s declared Skill-tag compatibility, Target Rules, and delivery frequency.

Weapon RT Delay resolves through the converted Pattern for Basic Attacks and for Skill Cards only when the Skill explicitly declares Weapon RT Delay Inheritance.';
UPDATE "project_rules" SET "topic"='Minimal current Skill tags are Direct Damage, Healing, Shield, Buff, Debuff, Utility, Summon, Physical, Fire, Water, Ice, Electric, Earth, Dark, Holy, and Poison. Physical is default non-elemental damage attribute. ADDED 2026-10-26 (USER RULING): card-visible requirement tags Single / Area / Weapon Shape, Melee / Ranged / Weapon Reach, Has Number, Costs MP, Weapon Scaling (definitions: frameworks ''Skill Tags'').' WHERE "id"=44 AND "topic" IS 'Minimal current Skill tags are Direct Damage, Healing, Shield, Buff, Debuff, Utility, Summon, Physical, Fire, Water, Ice, Electric, Earth, Dark, Holy, and Poison. Physical is default non-elemental damage attribute.';
UPDATE "project_rules" SET "topic"='Weapon-passive compatibility is determined only by Skill tags (REVISED 2026-10-26 USER RULING: Target Rules are no longer used for compatibility; weapon-derived tags are resolved from the equipped weapon). Each passive declares compatible tags, effect, delivery frequency, timing, and restrictions.' WHERE "id"=46 AND "topic" IS 'Weapon-passive compatibility is determined only by Skill effect tags and Target Rules. Each passive declares compatible tags/rules, effect, delivery frequency, timing, and restrictions.';
INSERT INTO "movement_targeting" ("section","topic","rule","notes") VALUES ('Targeting Rules','Tile targeting - "Any Tile" (USER RULING 2026-10-26)','Target Rules "Any Tile" = the skill is aimed at a tile and affects whatever is on that tile (or in the pattern placed from it): enemy, ally, neutral or object. An empty tile is still a legal aim point and still gets terrain/tile reactions. Applies to every damage and healing skill (single or area) and to the buff/debuff skills that used to be locked to one side: Stone Prison, Seal of Silence, Blinding Flash, Mind Fracture, Wither, Veil of Weakness, Nature''s Grasp, Arcane Barrier, Vital Barrier, Weapon Ward, Bastion Projection, Guardian''s Projection, Benediction, Invigorate, Arcane Renewal, Purifying Form, Coordinated Advance, Meditate. The old wording "Ground, including occupied Ground" is merged into "Any Tile" (same behaviour, one wording). Friendly fire is the default; any exception must be printed on the card.','Recorded 2026-10-26 by Designer from handoff artifacts/Designer_Handoff_Tags_Only_Compatibility.md + parent corrections A-C. DEV CHANGE PENDING. Not Studio-tested. skills.Target_Rules = ''Any Tile'' on 74 skills.');
INSERT INTO "movement_targeting" ("section","topic","rule","notes") VALUES ('Targeting Rules','"Caster Area" (USER RULING 2026-10-26)','Target Rules "Caster Area" = the skill is centered on the caster and is not aimed; it affects every unit in its area, on any side (the "either side" ruling applied to an area). Skills: War Cry, Bulwark Field, Consecrate, Sanctify (user ruling). Also set by Designer under the same rule (caster-centered, not aimable): Thunderclap, Static Field, Venom Burst, Siphon Pulse - pending user confirmation. Caster Area skills get no Reach tag.','Recorded 2026-10-26 by Designer from handoff artifacts/Designer_Handoff_Tags_Only_Compatibility.md + parent corrections A-C. DEV CHANGE PENDING. Not Studio-tested. CONFLICT FLAGGED, NOT CHANGED: Consecrate, Bulwark Field, Static Field and Thunderclap (and 7 Any Tile skills - see open_decisions 106) still carry the ''Allies Exempt'' skill property, which contradicts ''any side'' - pending user decision. Empowering Aura (''Self (Aura)'') was not part of the ruling and is unchanged (pending).');
INSERT INTO "movement_targeting" ("section","topic","rule","notes") VALUES ('Targeting Rules','Unit-targeted carve-outs (USER RULING 2026-10-24 / 2026-10-26)','These skills stay unit-targeted with Target Rules unchanged: Steal (SKL-STEAL), Mug (DOC-THIEF-01), Phantom Exchange (SKL-PHANTOM-EXCHANGE), Fated Escape (SKL-FATED-ESCAPE), Life Link (SKL-LIFE-LINK), Skyfall Lance (SKL-SKYFALL-LANCE), Reckless Charge (DOC-BERSERKER-01). Matches the code carve-out list (TargetingService TILE_TARGETING_CARVEOUTS, ruled 2026-10-24). Dragon Dive (SKL-DRAGON-DIVE, ''Enemy Tile'', a dash that lands on the target tile) is kept unchanged with the dash carve-outs - pending user confirmation. Also unchanged: Self-only skills, Empty Tile skills (Blink, Opportunist''s Step, traps, summons, Conjure Ice Spike), KO-unit revive skills, and the Object-target skill (Repair).','Recorded 2026-10-26 by Designer from handoff artifacts/Designer_Handoff_Tags_Only_Compatibility.md + parent corrections A-C. DEV CHANGE PENDING. Not Studio-tested.');
INSERT INTO "movement_targeting" ("section","topic","rule","notes") VALUES ('Targeting Rules','Enemy AI target choice (USER RULING 2026-10-24, kept 2026-10-26)','Enemy AI keeps side-based target choice (earlier "players only" ruling, 2026-10-24): tile targeting and friendly fire change what a skill can hit, not how the AI chooses. The AI picks targets by the skill''s harmful or beneficial intent, read from its tags.','Recorded 2026-10-26 by Designer from handoff artifacts/Designer_Handoff_Tags_Only_Compatibility.md + parent corrections A-C. DEV CHANGE PENDING. Not Studio-tested.');
INSERT INTO "frameworks" ("system","field_or_topic","rule") VALUES ('Augments','Tags-only compatibility (USER RULING 2026-10-26)','An Augment fits a Skill only by the tags printed on the Skill card - no hidden rules. Required Target Rules are no longer used (all None) and ''target must be enemy/ally'' requirements are dropped; Required Pattern is expressed as a Single/Area tag instead (None). Required Skill Tags format: comma-separated entries are ALL required (AND); alternatives inside one entry are joined with '' OR '' (e.g. ''Direct Damage, Single, Ranged''; ''Buff OR Healing OR Support''). Skills whose shape or reach comes from the equipped weapon carry ''Weapon Shape'' / ''Weapon Reach''; at runtime these are replaced by the equipped weapon''s actual Single/Area and Melee/Ranged tags, and the card shows them. If a weapon swap breaks a fit, the augment greys out and says why (Disarmed does not affect this). Other Requirements is kept only for battle-time conditions (Interrupt, Priority Surge), which are not equip rules. Weapon passives follow the same tags-only rule.');
INSERT INTO "frameworks" ("system","field_or_topic","rule") VALUES ('Augments','Kill-credit definition (USER RULING 2026-10-26)','All 16 kill augments (Executioner, Blood Harvest, Soul Harvest, Triumphant Recovery, Purifying Kill, Fortify on Kill, Momentum, Chain Kill, Explosive Death, Shattering Death, Terrifying Death, Toxic Death, Overkill Splash, Soul Echo, Gold Harvest, Treasure Hunter) trigger only when the supported Skill defeats an enemy that was NOT summoned (by a skill, augment or item) and has NOT been revived this battle. Count: mid-battle reinforcements, hostile event units, neutrals that have turned hostile; a Traitor counts if it dies while still an enemy. Do not count: allies, neutrals, objects, summoned units, revived units (Chaos Necromancer''s raised undead are revives). Applies both ways. Same definition in trigger_safety TRG-006 / TRG-007 / TRG-008 and in each augment''s Kill_Credit_Dependency.');
INSERT INTO "frameworks" ("system","field_or_topic","rule") VALUES ('Augments','Extra-hit target rules (USER RULING 2026-10-26)','Friendly fire is the default for extra hits. Enemies only (printed on the card): Bounce Shot, Overkill Splash, Toxic Death, Shattering Death, Terrifying Death, Soul Echo. Any side: Piercing Shot (the unit behind the target), Wide Arc (units on the adjacent tiles). Unchanged as written: Mass Purge, Turret Spawn, Holy Ground. Explosive Death and Impact Splash already hit everything.');
INSERT INTO "frameworks" ("system","field_or_topic","rule") VALUES ('Augments','Saved units - augments that no longer fit (USER RULING 2026-10-26)','When a save loads, any equipped augment that no longer fits its skill under the tags-only check is unequipped automatically and returned to the inventory. A short notice lists what was removed; its exact wording needs the user''s approval before it is added (standing rule: no new helper text without approval). Enemy units need no migration - they are generated fresh each battle from the same check.');
INSERT INTO "open_decisions" ("OPEN_DECISIONS_&_PARKED_TOPICS","col_2","col_3","col_4","col_5","col_6","col_7") VALUES ('106','Tags-only augment compatibility - items left unchanged pending user wording (2026-10-26)','OPEN - needs user wording','Left unchanged by the 2026-10-26 tags-only pass: (1) Wet Ground / Frozen Ground / Poison Cloud - Other_Requirements garbled (''Water;  or Ground'' etc.), still carry Required Target Rules ''Enemy Unit''. (2) Line Projection - ''Target Rules include a Unit'' (meaningless under tile targeting?). (3) Shared Resolve - Self-only + must-not-apply list; also missing from AugmentData.lua. (4) Lucky Strike / Rapid Assault / Precise Disarm - Targeting_Range says ''See 06 SKILLS!U86''; real text not in the DB, so no Reach tag was added (all three are ''Projectile: Inherit''). (5) Empowering Aura - ''Self (Aura)'' Target Rules not covered by the ruling. (6) Dragon Dive - kept ''Enemy Tile'' with the dash carve-outs; confirm. (7) Thunderclap / Static Field / Venom Burst / Siphon Pulse set to ''Caster Area'' by Designer (caster-centered, not aimable); confirm. (8) ''Allies Exempt'' skill property is still on 11 skills that are now any-side (Static Field, Consecrate, Blinding Flash, Mending Rain, Seal of Silence, Bulwark Field, Invigorate, Arcane Renewal, Benediction, Purge, Thunderclap) - keep or remove? (9) Erosion / Raise Earth (Parked) still carry Required Target Rules ''Ground''; need a tag when unparked.','None','None','None');
COMMIT;